CREATE TYPE public.app_role AS ENUM ('admin','agent','client','branch_manager');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL DEFAULT 'client', UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(who uuid, wanted public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=who AND role=wanted) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE POLICY role_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_customer_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name',NEW.raw_user_meta_data->>'name',''),120)); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'client'); RETURN NEW; END $$;
CREATE TRIGGER customer_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_customer_profile();
CREATE TABLE public.registrations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category text NOT NULL CHECK(category IN ('branch','person','business','owner')), name text NOT NULL CHECK(length(name) BETWEEN 2 AND 160), code text, document text, email text NOT NULL, phone text NOT NULL, whatsapp text, address text NOT NULL DEFAULT '', trade_name text, state_registration text, contact_name text, birth_date date, job_title text, branch_id uuid REFERENCES public.registrations(id), user_id uuid REFERENCES public.profiles(id), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.registrations TO authenticated; GRANT ALL ON public.registrations TO service_role;
ALTER TABLE public.registrations ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX registration_document_unique ON public.registrations(category,document) WHERE document IS NOT NULL AND document <> '';
CREATE UNIQUE INDEX branch_code_unique ON public.registrations(code) WHERE category='branch';
CREATE INDEX registration_branch_idx ON public.registrations(branch_id); CREATE INDEX registration_user_idx ON public.registrations(user_id);
CREATE TABLE public.branch_access (user_id uuid NOT NULL REFERENCES public.profiles(id), branch_id uuid NOT NULL REFERENCES public.registrations(id), PRIMARY KEY(user_id,branch_id));
GRANT SELECT ON public.branch_access TO authenticated; GRANT ALL ON public.branch_access TO service_role;
ALTER TABLE public.branch_access ENABLE ROW LEVEL SECURITY;
CREATE POLICY branch_access_read ON public.branch_access FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.manages_branch(who uuid, branch uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(who,'branch_manager') AND EXISTS(SELECT 1 FROM public.branch_access WHERE user_id=who AND branch_id=branch) $$;
REVOKE ALL ON FUNCTION public.manages_branch(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.manages_branch(uuid,uuid) TO authenticated;
CREATE POLICY registration_read ON public.registrations FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR public.manages_branch(auth.uid(),CASE WHEN category='branch' THEN id ELSE branch_id END));
CREATE TABLE public.owner_relationships (owner_id uuid NOT NULL REFERENCES public.registrations(id), linked_id uuid NOT NULL REFERENCES public.registrations(id), PRIMARY KEY(owner_id,linked_id), CHECK(owner_id<>linked_id));
GRANT SELECT ON public.owner_relationships TO authenticated; GRANT ALL ON public.owner_relationships TO service_role;
ALTER TABLE public.owner_relationships ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_links_read ON public.owner_relationships FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.registrations WHERE id=owner_id));
CREATE TABLE public.conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), client_id uuid NOT NULL REFERENCES public.profiles(id), branch_id uuid REFERENCES public.registrations(id), subject text NOT NULL DEFAULT 'Atendimento Maison' CHECK(length(subject) BETWEEN 1 AND 160), status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','closed')), assigned_to uuid REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.conversations TO authenticated; GRANT ALL ON public.conversations TO service_role;
ALTER TABLE public.conversations ENABLE ROW LEVEL SECURITY;
CREATE INDEX conversation_client_idx ON public.conversations(client_id); CREATE INDEX conversation_branch_idx ON public.conversations(branch_id); CREATE INDEX conversation_agent_idx ON public.conversations(assigned_to);
CREATE FUNCTION public.can_read_conversation(who uuid, conversation uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.conversations c WHERE c.id=conversation AND (c.client_id=who OR public.has_role(who,'admin') OR public.manages_branch(who,c.branch_id) OR (c.assigned_to=who AND public.has_role(who,'agent')))) $$;
REVOKE ALL ON FUNCTION public.can_read_conversation(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_read_conversation(uuid,uuid) TO authenticated;
CREATE POLICY conversation_read ON public.conversations FOR SELECT TO authenticated USING(public.can_read_conversation(auth.uid(),id));
CREATE TABLE public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES public.conversations(id), sender_id uuid NOT NULL REFERENCES public.profiles(id), body text NOT NULL CHECK(length(trim(body)) BETWEEN 1 AND 4000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.messages TO authenticated; GRANT ALL ON public.messages TO service_role;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE INDEX message_conversation_idx ON public.messages(conversation_id,created_at);
CREATE POLICY message_read ON public.messages FOR SELECT TO authenticated USING(public.can_read_conversation(auth.uid(),conversation_id));
CREATE TABLE public.conversation_reads (conversation_id uuid NOT NULL REFERENCES public.conversations(id), user_id uuid NOT NULL REFERENCES public.profiles(id), last_read_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(conversation_id,user_id));
GRANT SELECT ON public.conversation_reads TO authenticated; GRANT ALL ON public.conversation_reads TO service_role;
ALTER TABLE public.conversation_reads ENABLE ROW LEVEL SECURITY;
CREATE POLICY receipt_read ON public.conversation_reads FOR SELECT TO authenticated USING(public.can_read_conversation(auth.uid(),conversation_id));
CREATE POLICY profile_support_read ON public.profiles FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.conversations c WHERE (c.client_id=id OR c.assigned_to=id) AND public.can_read_conversation(auth.uid(),c.id)) OR (public.has_role(auth.uid(),'branch_manager') AND EXISTS(SELECT 1 FROM public.branch_access a WHERE a.user_id=id AND public.manages_branch(auth.uid(),a.branch_id))));
CREATE POLICY registration_agent_read ON public.registrations FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'agent') AND category='person' AND EXISTS(SELECT 1 FROM public.conversations c WHERE c.client_id=user_id AND c.assigned_to=auth.uid()));
CREATE FUNCTION public.valid_document(value text, kind text) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE d text:=regexp_replace(value,'\D','','g'); n int; i int; s int; digit int; weights int[]; BEGIN IF kind='cpf' THEN n:=11; ELSE n:=14; END IF; IF length(d)<>n OR d=repeat(substr(d,1,1),n) THEN RETURN false; END IF; FOR digit IN 1..2 LOOP s:=0; IF n=11 THEN FOR i IN 1..(8+digit) LOOP s:=s+substr(d,i,1)::int*(10+digit-i); END LOOP; s:=(s*10)%11; IF s=10 THEN s:=0; END IF; ELSE IF digit=1 THEN weights:=ARRAY[5,4,3,2,9,8,7,6,5,4,3,2]; ELSE weights:=ARRAY[6,5,4,3,2,9,8,7,6,5,4,3,2]; END IF; FOR i IN 1..array_length(weights,1) LOOP s:=s+substr(d,i,1)::int*weights[i]; END LOOP; s:=s%11; IF s<2 THEN s:=0; ELSE s:=11-s; END IF; END IF; IF s<>substr(d,n-2+digit,1)::int THEN RETURN false; END IF; END LOOP; RETURN true; END $$;
CREATE FUNCTION public.save_registration(record_id uuid, payload jsonb, links uuid[] DEFAULT '{}') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE who uuid:=auth.uid(); r public.registrations; target uuid:=record_id; cat text:=payload->>'category'; branch uuid:=nullif(payload->>'branch_id','')::uuid; owner_user uuid:=nullif(payload->>'user_id','')::uuid; doc text:=regexp_replace(coalesce(payload->>'document',''),'\D','','g'); isadmin boolean:=public.has_role(who,'admin'); manager boolean; linked uuid; BEGIN IF who IS NULL THEN RAISE EXCEPTION 'Acesso necessário'; END IF; IF cat NOT IN ('branch','person','business','owner') THEN RAISE EXCEPTION 'Categoria inválida'; END IF; IF target IS NOT NULL THEN SELECT * INTO r FROM public.registrations WHERE id=target; IF NOT FOUND THEN RAISE EXCEPTION 'Cadastro não encontrado'; END IF; IF r.category<>cat THEN RAISE EXCEPTION 'Categoria não pode ser alterada'; END IF; END IF; manager:=public.manages_branch(who,CASE WHEN cat='branch' THEN target ELSE branch END); IF NOT isadmin AND NOT manager THEN IF cat<>'person' OR (target IS NOT NULL AND r.user_id IS DISTINCT FROM who) THEN RAISE EXCEPTION 'Sem permissão'; END IF; owner_user:=who; branch:=r.branch_id; END IF; IF manager AND NOT isadmin AND (cat='branch' OR (target IS NOT NULL AND NOT public.manages_branch(who,r.branch_id))) THEN RAISE EXCEPTION 'Sem permissão para esta filial'; END IF; IF branch IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.registrations WHERE id=branch AND category='branch' AND active) THEN RAISE EXCEPTION 'Filial inválida ou inativa'; END IF; IF length(trim(coalesce(payload->>'name','')))<2 OR length(payload->>'name')>160 THEN RAISE EXCEPTION 'Informe um nome válido'; END IF; IF coalesce(payload->>'email','') !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(payload->>'email')>254 THEN RAISE EXCEPTION 'E-mail inválido'; END IF; IF length(regexp_replace(coalesce(payload->>'phone',''),'\D','','g')) NOT BETWEEN 10 AND 13 THEN RAISE EXCEPTION 'Telefone inválido'; END IF; IF coalesce(payload->>'whatsapp','')<>'' AND length(regexp_replace(payload->>'whatsapp','\D','','g')) NOT BETWEEN 10 AND 13 THEN RAISE EXCEPTION 'WhatsApp inválido'; END IF; IF cat IN ('person','owner') AND NOT public.valid_document(doc,'cpf') THEN RAISE EXCEPTION 'CPF inválido'; END IF; IF (cat='business' OR (cat='branch' AND doc<>'')) AND NOT public.valid_document(doc,'cnpj') THEN RAISE EXCEPTION 'CNPJ inválido'; END IF; IF cat='branch' AND (length(trim(coalesce(payload->>'code','')))<1 OR length(trim(coalesce(payload->>'contact_name','')))<2) THEN RAISE EXCEPTION 'Informe código e responsável'; END IF; IF cat='business' AND length(trim(coalesce(payload->>'contact_name','')))<2 THEN RAISE EXCEPTION 'Informe o responsável'; END IF; IF cat<>'owner' AND length(trim(coalesce(payload->>'address','')))<8 THEN RAISE EXCEPTION 'Informe o endereço completo'; END IF; IF length(coalesce(payload->>'address',''))>600 OR length(coalesce(payload->>'contact_name',''))>160 OR length(coalesce(payload->>'trade_name',''))>160 OR length(coalesce(payload->>'job_title',''))>120 THEN RAISE EXCEPTION 'Campo muito longo'; END IF; IF nullif(payload->>'birth_date','')::date>current_date THEN RAISE EXCEPTION 'Nascimento não pode estar no futuro'; END IF; IF NOT isadmin AND NOT manager AND target IS NULL AND EXISTS(SELECT 1 FROM public.registrations WHERE category='person' AND user_id=who) THEN RAISE EXCEPTION 'Você já possui cadastro'; END IF; IF target IS NULL THEN INSERT INTO public.registrations(category,name,email,phone) VALUES(cat,trim(payload->>'name'),lower(trim(payload->>'email')),payload->>'phone') RETURNING id INTO target; END IF; UPDATE public.registrations SET name=trim(payload->>'name'),code=nullif(payload->>'code',''),document=nullif(doc,''),email=lower(trim(payload->>'email')),phone=payload->>'phone',whatsapp=nullif(payload->>'whatsapp',''),address=coalesce(payload->>'address',''),trade_name=nullif(payload->>'trade_name',''),state_registration=nullif(payload->>'state_registration',''),contact_name=nullif(payload->>'contact_name',''),birth_date=nullif(payload->>'birth_date','')::date,job_title=nullif(payload->>'job_title',''),branch_id=branch,user_id=CASE WHEN isadmin OR manager THEN owner_user ELSE who END,updated_at=now() WHERE id=target; IF cat='owner' THEN IF coalesce(array_length(links,1),0)>50 THEN RAISE EXCEPTION 'Muitos vínculos'; END IF; FOREACH linked IN ARRAY links LOOP IF NOT EXISTS(SELECT 1 FROM public.registrations WHERE id=linked AND category IN ('business','branch') AND (isadmin OR public.manages_branch(who,CASE WHEN category='branch' THEN id ELSE branch_id END))) THEN RAISE EXCEPTION 'Vínculo sem permissão'; END IF; END LOOP; DELETE FROM public.owner_relationships WHERE owner_id=target; INSERT INTO public.owner_relationships(owner_id,linked_id) SELECT target,l FROM unnest(links) l; END IF; RETURN target; END $$;
REVOKE ALL ON FUNCTION public.save_registration(uuid,jsonb,uuid[]) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.save_registration(uuid,jsonb,uuid[]) TO authenticated;
CREATE FUNCTION public.set_registration_active(record_id uuid, enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.registrations; BEGIN SELECT * INTO r FROM public.registrations WHERE id=record_id; IF NOT FOUND OR NOT (public.has_role(auth.uid(),'admin') OR (r.category<>'branch' AND public.manages_branch(auth.uid(),r.branch_id))) THEN RAISE EXCEPTION 'Sem permissão'; END IF; UPDATE public.registrations SET active=enabled,updated_at=now() WHERE id=record_id; END $$;
REVOKE ALL ON FUNCTION public.set_registration_active(uuid,boolean) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.set_registration_active(uuid,boolean) TO authenticated;
CREATE FUNCTION public.support_action(action text, conversation uuid DEFAULT NULL, payload jsonb DEFAULT '{}') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE who uuid:=auth.uid(); c public.conversations; branch uuid; agent uuid; body text; BEGIN IF who IS NULL THEN RAISE EXCEPTION 'Acesso necessário'; END IF; IF action='create' THEN IF NOT EXISTS(SELECT 1 FROM public.registrations WHERE user_id=who AND category='person' AND active) THEN RAISE EXCEPTION 'Complete seu cadastro antes de conversar'; END IF; branch:=nullif(payload->>'branch_id','')::uuid; IF branch IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.registrations WHERE id=branch AND category='branch' AND active) THEN RAISE EXCEPTION 'Filial inválida'; END IF; IF length(coalesce(payload->>'subject','Atendimento Maison')) NOT BETWEEN 1 AND 160 THEN RAISE EXCEPTION 'Assunto inválido'; END IF; INSERT INTO public.conversations(client_id,branch_id,subject) VALUES(who,branch,coalesce(payload->>'subject','Atendimento Maison')) RETURNING id INTO conversation; RETURN conversation; END IF; IF NOT public.can_read_conversation(who,conversation) THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT * INTO c FROM public.conversations WHERE id=conversation FOR UPDATE; IF action='send' THEN IF c.status='closed' THEN RAISE EXCEPTION 'Conversa encerrada'; END IF; body:=trim(payload->>'body'); IF body IS NULL OR length(body) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION 'Mensagem inválida'; END IF; INSERT INTO public.messages(conversation_id,sender_id,body) VALUES(conversation,who,body); UPDATE public.conversations SET updated_at=now() WHERE id=conversation; ELSIF action='read' THEN INSERT INTO public.conversation_reads(conversation_id,user_id,last_read_at) VALUES(conversation,who,now()) ON CONFLICT(conversation_id,user_id) DO UPDATE SET last_read_at=now(); ELSIF action='status' THEN IF NOT (public.has_role(who,'admin') OR public.manages_branch(who,c.branch_id) OR (public.has_role(who,'agent') AND c.assigned_to=who)) THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF payload->>'status' NOT IN ('open','in_progress','closed') THEN RAISE EXCEPTION 'Status inválido'; END IF; UPDATE public.conversations SET status=payload->>'status',updated_at=now() WHERE id=conversation; ELSIF action='assign' THEN IF NOT (public.has_role(who,'admin') OR public.manages_branch(who,c.branch_id)) THEN RAISE EXCEPTION 'Sem permissão'; END IF; agent:=nullif(payload->>'assigned_to','')::uuid; IF agent IS NOT NULL AND NOT (public.has_role(agent,'agent') AND (public.has_role(who,'admin') OR EXISTS(SELECT 1 FROM public.branch_access WHERE user_id=agent AND branch_id=c.branch_id))) THEN RAISE EXCEPTION 'Atendente não autorizado'; END IF; UPDATE public.conversations SET assigned_to=agent,updated_at=now() WHERE id=conversation; ELSE RAISE EXCEPTION 'Ação inválida'; END IF; RETURN conversation; END $$;
REVOKE ALL ON FUNCTION public.support_action(text,uuid,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.support_action(text,uuid,jsonb) TO authenticated;
CREATE FUNCTION public.manage_access(target_user uuid, wanted_role public.app_role, branches uuid[] DEFAULT '{}') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b uuid; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF target_user=auth.uid() THEN RAISE EXCEPTION 'Não altere seu próprio acesso'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=target_user) THEN RAISE EXCEPTION 'Usuário inexistente'; END IF; FOREACH b IN ARRAY branches LOOP IF NOT EXISTS(SELECT 1 FROM public.registrations WHERE id=b AND category='branch' AND active) THEN RAISE EXCEPTION 'Filial inválida'; END IF; END LOOP; IF wanted_role='branch_manager' AND coalesce(array_length(branches,1),0)=0 THEN RAISE EXCEPTION 'Selecione uma filial'; END IF; DELETE FROM public.user_roles WHERE user_id=target_user; INSERT INTO public.user_roles(user_id,role) VALUES(target_user,wanted_role); DELETE FROM public.branch_access WHERE user_id=target_user; INSERT INTO public.branch_access(user_id,branch_id) SELECT target_user,b FROM unnest(branches) b; END $$;
REVOKE ALL ON FUNCTION public.manage_access(uuid,public.app_role,uuid[]) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.manage_access(uuid,public.app_role,uuid[]) TO authenticated;
CREATE FUNCTION public.public_branch_directory() RETURNS TABLE(id uuid,name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT id,name FROM public.registrations WHERE category='branch' AND active ORDER BY name $$;
REVOKE ALL ON FUNCTION public.public_branch_directory() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.public_branch_directory() TO authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.messages,public.conversations,public.conversation_reads;